{
  "PROP-6a4369e9-inv-028": {
    "property_id": "PROP-6a4369e9-inv-028",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-028",
      "classification": "vulnerability",
      "code_path": "beacon_node/lighthouse_network/src/rpc/protocol.rs::currently_supported::L396-401",
      "proof_trace": "BlobsByRange protocol remains in supported_protocols list forever (conditional only on Deneb fork existence, not epoch). No code rejects requests after FULU_FORK_EPOCH + MIN_EPOCHS. Handler only validates availability boundary for pruning, not deprecation.",
      "attack_scenario": "After FULU activation + MIN_EPOCHS, attacker sends BlobsByRange requests to force nodes to serve deprecated blob data instead of data columns, bypassing PeerDAS migration and enabling resource exhaustion via dual serving obligations.",
      "checklist_id": "PROP-6a4369e9-inv-028"
    },
    "text": "blob_sidecars_by_range must be fully deprecated after FULU_FORK_EPOCH + MIN_EPOCHS.",
    "assertion": "current_epoch >= FULU_FORK_EPOCH + MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS => respond_empty_or_reject",
    "covers": "SG-011",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

